@Override
public void onNext(R t) {
    emitInnerValue(parent, queue, t);
}

void emitInnerValue(SwitchMapObserver<T, R> o, SimpleQueue<R> q, R t) {
    if (index != o.unique) {
        return;
    }
    if (q == null) {
        // The inner observer may have been cancelled before its onSubscribe
        // could create the queue (e.g., the downstream disposed itself from
        // within onSubscribe), so there is nowhere to enqueue the value.
        o.drain();
        return;
    }

